test('sampled attempt elapsed time is labeled as an estimate', () => {
    const h = highlighter();
    const executionProfile = profile();
    executionProfile.attempts.push({ stageId: '0', strategy: 'native', status: 'COMPLETED',
        estimatedMillis: 1, elapsedNanos: 10000000,
        metrics: { activeTime: { count: 10000000, unit: 'ns', origin: 'sampled', state: 'complete', scope: 'activeProducerWork' } } });
    const text = h.format({ type: 'Group', executionProfile }, 'Telemetry').text;
    assert.match(text, /sampled estimate 10.0ms/);
    assert.doesNotMatch(text, /; observed 10.0ms/);
});
